import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p86_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor depthwise_separable_fused_cuda(
    torch::Tensor x,
    torch::Tensor dw_weight,
    torch::Tensor dw_bias,
    torch::Tensor pw_weight,
    torch::Tensor pw_bias,
    int stride,
    int padding,
    int dilation
);

torch::Tensor depthwise_separable_fused(
    torch::Tensor x,
    torch::Tensor dw_weight,
    torch::Tensor dw_bias,
    torch::Tensor pw_weight,
    torch::Tensor pw_bias,
    int stride,
    int padding,
    int dilation
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    return depthwise_separable_fused_cuda(x, dw_weight, dw_bias, pw_weight, pw_bias, stride, padding, dilation);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("depthwise_separable_fused", &depthwise_separable_fused, "Fused depthwise-separable conv (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused depthwise (3x3, s=1, p=1, d=1) + pointwise (1x1) kernel
// Grid: (N * C_in * ceil(H/TH) * ceil(W/TW), C_out_blocks)
// Each block handles a spatial tile TH x TW for one (n, c_in_group) and C_OUT_BLOCK output channels

#define TH 8
#define TW 8
#define HALO 1
#define SMEM_H (TH + 2*HALO)
#define SMEM_W (TW + 2*HALO)
#define C_OUT_BLOCK 16

__global__ void __launch_bounds__(TH*TW, 4)
depthwise_separable_fused_kernel(
    const float* __restrict__ input,      // [N, Cin, H, W]
    const float* __restrict__ dw_weight,  // [Cin, 1, 3, 3]
    const float* __restrict__ dw_bias,    // [Cin] or null
    const float* __restrict__ pw_weight,  // [Cout, Cin, 1, 1]
    const float* __restrict__ pw_bias,    // [Cout] or null
    float* __restrict__ output,           // [N, Cout, H, W]
    int N, int Cin, int Cout, int H, int W,
    int tiles_w, int tiles_h,
    bool has_dw_bias, bool has_pw_bias
) {
    // blockIdx.x encodes: n * Cin * tiles_h * tiles_w + c * tiles_h * tiles_w + th * tiles_w + tw
    int idx = blockIdx.x;
    int tw_idx = idx % tiles_w; idx /= tiles_w;
    int th_idx = idx % tiles_h; idx /= tiles_h;
    int c = idx % Cin; idx /= Cin;
    int n = idx;

    int cout_block = blockIdx.y;  // which C_OUT_BLOCK chunk of output channels
    int cout_start = cout_block * C_OUT_BLOCK;
    int cout_end = min(cout_start + C_OUT_BLOCK, Cout);

    int out_row_start = th_idx * TH;
    int out_col_start = tw_idx * TW;

    // Thread index within the tile
    int t = threadIdx.x;
    int tr = t / TW;
    int tc = t % TW;

    // Load input halo into shared memory
    __shared__ float smem[SMEM_H * SMEM_W];

    // Cooperative load of (TH+2) x (TW+2) input tile
    int total_smem = SMEM_H * SMEM_W;
    int threads = TH * TW;
    const float* in_ptr = input + n * Cin * H * W + c * H * W;

    for (int i = t; i < total_smem; i += threads) {
        int sr = i / SMEM_W;
        int sc = i % SMEM_W;
        int in_r = out_row_start - HALO + sr;
        int in_c = out_col_start - HALO + sc;
        if (in_r >= 0 && in_r < H && in_c >= 0 && in_c < W) {
            smem[i] = in_ptr[in_r * W + in_c];
        } else {
            smem[i] = 0.0f;
        }
    }
    __syncthreads();

    // Compute depthwise output for this thread's pixel
    int out_r = out_row_start + tr;
    int out_c = out_col_start + tc;
    bool valid = (out_r < H && out_c < W);

    float dw_out = 0.0f;
    if (valid) {
        const float* kw = dw_weight + c * 9;  // [Cin, 1, 3, 3] -> channel c, 9 coeffs
        #pragma unroll
        for (int kr = 0; kr < 3; kr++) {
            #pragma unroll
            for (int kc = 0; kc < 3; kc++) {
                float w = kw[kr * 3 + kc];
                float v = smem[(tr + kr) * SMEM_W + (tc + kc)];
                dw_out += w * v;
            }
        }
        if (has_dw_bias) dw_out += dw_bias[c];
    }

    // Now apply pointwise: for each output channel in [cout_start, cout_end)
    // pw_weight: [Cout, Cin, 1, 1] -> pw_weight[co * Cin + c]
    if (valid) {
        for (int co = cout_start; co < cout_end; co++) {
            float pw_w = pw_weight[co * Cin + c];
            float pw_val = dw_out * pw_w;
            // Atomic add to output since multiple c channels contribute
            atomicAdd(&output[n * Cout * H * W + co * H * W + out_r * W + out_c], pw_val);
        }
        // Add pw bias once per output channel (only from c==0 to avoid double-adding)
        if (has_pw_bias && c == 0) {
            for (int co = cout_start; co < cout_end; co++) {
                atomicAdd(&output[n * Cout * H * W + co * H * W + out_r * W + out_c], pw_bias[co]);
            }
        }
    }
}

torch::Tensor depthwise_separable_fused_cuda(
    torch::Tensor x,
    torch::Tensor dw_weight,
    torch::Tensor dw_bias,
    torch::Tensor pw_weight,
    torch::Tensor pw_bias,
    int stride,
    int padding,
    int dilation
) {
    // Only handle the specialized fast path
    if (stride != 1 || padding != 1 || dilation != 1 ||
        !x.is_contiguous() || !dw_weight.is_contiguous() || !pw_weight.is_contiguous()) {
        return torch::Tensor(); // signal fallback
    }

    int N = x.size(0);
    int Cin = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int Cout = pw_weight.size(0);

    // Check dw_weight shape: [Cin, 1, 3, 3]
    if (dw_weight.size(0) != Cin || dw_weight.size(2) != 3 || dw_weight.size(3) != 3) {
        return torch::Tensor();
    }

    auto output = torch::zeros({N, Cout, H, W}, x.options());

    bool has_dw_bias = dw_bias.defined() && dw_bias.numel() > 0;
    bool has_pw_bias = pw_bias.defined() && pw_bias.numel() > 0;

    int tiles_h = (H + TH - 1) / TH;
    int tiles_w = (W + TW - 1) / TW;
    int cout_blocks = (Cout + C_OUT_BLOCK - 1) / C_OUT_BLOCK;

    dim3 grid(N * Cin * tiles_h * tiles_w, cout_blocks);
    dim3 block(TH * TW);

    depthwise_separable_fused_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        dw_weight.data_ptr<float>(),
        has_dw_bias ? dw_bias.data_ptr<float>() : nullptr,
        pw_weight.data_ptr<float>(),
        has_pw_bias ? pw_bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N, Cin, Cout, H, W,
        tiles_w, tiles_h,
        has_dw_bias, has_pw_bias
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a depthwise-separable 2D convolution operation.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            padding (int, optional): Padding applied to the input. Defaults to 0.
            dilation (int, optional): Spacing between kernel elements. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.depthwise = nn.Conv2d(in_channels, in_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)
        self.pointwise = nn.Conv2d(in_channels, out_channels, kernel_size=1, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        fast_out = None
        use_fast = (
            x.is_cuda and
            x.dtype == torch.float32 and
            x.is_contiguous() and
            self.depthwise.weight.is_contiguous() and
            self.pointwise.weight.is_contiguous() and
            self.depthwise.groups == self.depthwise.in_channels and
            self.depthwise.kernel_size == (3, 3) and
            self.depthwise.stride == (1, 1) and
            self.depthwise.padding == (1, 1) and
            self.depthwise.dilation == (1, 1)
        )
        if use_fast:
            dw_bias_t = self.depthwise.bias if self.depthwise.bias is not None else torch.empty(0, device=x.device)
            pw_bias_t = self.pointwise.bias if self.pointwise.bias is not None else torch.empty(0, device=x.device)
            result = _stark_get_extension().depthwise_separable_fused(
                x,
                self.depthwise.weight,
                dw_bias_t,
                self.pointwise.weight,
                pw_bias_t,
                self.depthwise.stride[0],
                self.depthwise.padding[0],
                self.depthwise.dilation[0],
            )
            if result is not None and result.numel() > 0:
                fast_out = result
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if fast_out is not None:
            return fast_out
        x = self.depthwise(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = self.pointwise(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        return x
        # <<<END_IMPROVE>>>

