    int sp_block = blockIdx.x;  // which group of PW_SP spatial positions
    int sp_base = sp_block * PW_SP;

    int cin_tid  = threadIdx.x;  // 0..PW_CIN-1
    int sp_tid   = threadIdx.y;  // 0..PW_SP-1

