    // Total elements: PW_COUT * PW_CIN = 128*64 = 8192
    // Total threads: PW_CIN * PW_SP = 64*4 = 256
    // Each thread loads 8192/256 = 32 elements
    int tid_flat = sp_tid * PW_CIN + cin_tid;
