// -----------------------------------------------------------------------

#define PW_CIN  64
#define PW_COUT 128
#define PW_BLOCK_X 32   // threads per spatial row (= warp size)
#define PW_BLOCK_Y 8    // spatial positions per block
#define PW_COUT_PER_THREAD (PW_COUT / PW_BLOCK_X)  // 4 output channels per thread

__global__ void __launch_bounds__(PW_BLOCK_X * PW_BLOCK_Y, 4)
