    const float* __restrict__ input,     // [N, PW_CIN, H, W] NCHW
    const float* __restrict__ pw_weight, // [PW_COUT, PW_CIN] (from [Cout,Cin,1,1])
    const float* __restrict__ pw_bias,   // [PW_COUT] or null
